class Solution {
    public int numberOfArrays(int[] differences,int lower,int upper){
        long prefix=0,minimum=0,maximum=0;
        for(int difference:differences){
            prefix+=difference;
            minimum=Math.min(minimum,prefix);
            maximum=Math.max(maximum,prefix);
        }
        return (int)Math.max(0L,(long)upper-lower-(maximum-minimum)+1);
    }
}

code.kotlin:
class Solution {
    fun numberOfArrays(differences:IntArray,lower:Int,upper:Int):Int{
        var prefix=0L;
        var minimum=0L;
        var maximum=0L;
        for(difference in differences){
            prefix+=difference;
            minimum=minOf(minimum,prefix);
            maximum=maxOf(maximum,prefix)
        };
        return maxOf(0L,upper.toLong()-lower-(maximum-minimum)+1).toInt()
    }
}

